            if (currentDifference < minDifference) {
                minDifference = currentDifference;
                closestPair.clear(); // Clear the list to store the new pair
                closestPair.add(numbers.get(i));
                closestPair.add(numbers.get(i + 1));
            }
        }

        return closestPair;
    }

