public int doAlgebra(List<String> operator, List<Integer> operand) {
    int result = operand.get(0);

    for (int i = 0; i < operator.size(); i++) {
        int nextOperand = operand.get(i + 1);
        switch (operator.get(i)) {
            case "+":
                result += nextOperand;
                break;
            case "-":
                result -= nextOperand;
                break;
            case "*":
                result *= nextOperand;
                break;
            case "/":
                result /= nextOperand;
                break;
            case "**":
                result = (int) Math.pow(result, nextOperand);
                break;
            default:
                throw new IllegalArgumentException("Invalid operator: " + operator.get(i));
        }
    }

    return result;
}
```

